.venv/bin/python - <<'PY'
from pathlib import Path
from datetime import datetime,timezone,timedelta
import hashlib,json,shutil,urllib.request
report_dir=Path('rag/eval/reports')
report=json.loads((report_dir/'mixed_v1_live_fault_scope_followup.json').read_text())
original=json.loads((report_dir/'mixed_v1_live_fault_scope_followup_unreviewed.json').read_text())
assert [r['response'] for r in report['challenge']]==[r['response'] for r in original['challenge']]
assert report['human_review_status']=='completed' and report['human_review_summary']['pass_cells']==24
for filename,sha in report['runtime_hashes'].items():assert hashlib.sha256(Path(filename).read_bytes()).hexdigest()==sha,filename
prior=json.loads((report_dir/'mixed_v1_live_run1.json').read_text())
for filename,sha in prior['runtime_hashes'].items():
    if filename!='rag/service/mixed_service.py':assert hashlib.sha256(Path(filename).read_bytes()).hexdigest()==sha,filename
frozen=Path('rag/eval/baselines/mixed_v1');frozen.mkdir(parents=True,exist_ok=False)
files=['rag/service/'+f for f in ('__init__.py','intent_classifier.py','store_contract.py','semantic_router.py','routing_prototypes.json','ticket_service.py','retrieval_server.py','mixed_service.py','answer_service.py')]
files+=['rag/retrieval/search_chunks.py','rag/eval/cases/routing_challenge_v1.jsonl','rag/eval/cases/routing_challenge_v1.manifest.json','rag/eval/verify_mixed_live.py','rag/eval/test_mixed_service.py']
files+=['rag/eval/reports/'+f for f in ('mixed_preflight_v1.json','mixed_v1_live_run1.json','mixed_v1_live_run1.md','mixed_v1_live_fault_scope_followup.json','mixed_v1_live_fault_scope_followup.md','mixed_v1_live_fault_scope_followup_unreviewed.json','mixed_v1_live_fault_scope_followup_unreviewed.md')]
files+=['docs/'+f for f in ('MIXED_QUERY_MILESTONE_2026-10-12.md','LANGGRAPH_TOOL_CONTRACT.md','ROUTING_STORE_CONTRACT.md')]
checksums={}
for filename in files:
    source=Path(filename);dest=frozen/filename
    assert source.name!='.env' and 'key' not in source.parts
    dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(source,dest)
    checksums[filename]=hashlib.sha256(dest.read_bytes()).hexdigest()
allowed={'RAG_MIXED_ENABLED','RAG_SQL_TICKET_ENABLED','RAG_SEMANTIC_ROUTING_ENABLED','LLM_MODEL'}
config={}
for line in Path('.env').read_text().splitlines():
    if '=' in line:
        k,v=line.split('=',1)
        if k in allowed:config[k]=v.strip().strip('"').strip("'")
config.setdefault('RAG_SQL_TICKET_ENABLED','1')
with urllib.request.urlopen('http://127.0.0.1:8100/health',timeout=10) as response:health=json.load(response)
assert health['model_ready']
manifest={'version':'mixed-v1','acceptance':'user_review_passed_4_of_4','frozen_at':datetime.now(timezone(timedelta(hours=8))).isoformat(),
    'file_sha256':checksums,'runtime_config':config,'routing_threshold':0.60,'routing_margin':0.06,
    'review_scope':'latest four synthetic mixed answers only; no scores transferred to first full regression',
    'review_summary':report['human_review_summary'],'full_regression_summary':prior['summary'],
    'latest_four_review_status':'completed','other_new_answers_review_status':'not_regraded',
    'langgraph_integrated':False,'no_secrets_archived':True,'health':health}
(frozen/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
print(json.dumps({'baseline':str(frozen),'files':len(files),'pass_cells':24,'accepted_cases':4,'health':health},ensure_ascii=False))
PY
